// Market Hours Check - 9:30 AM to 4:00 PM ET
// Also skip if no alerts needed (outside trading window)

const now = new Date();

// Convert to ET
const etString = now.toLocaleString('en-US', { timeZone: 'America/New_York' });
const etDate = new Date(etString);
const hours = etDate.getHours();
const minutes = etDate.getMinutes();
const timeInMinutes = hours * 60 + minutes;

// Market hours: 9:30 AM (570 min) to 4:00 PM (960 min)
const MARKET_OPEN = 9 * 60 + 30;  // 570
const MARKET_CLOSE = 16 * 60;      // 960

const isMarketHours = timeInMinutes >= MARKET_OPEN && timeInMinutes < MARKET_CLOSE;

if (!isMarketHours) {
  // Return empty to signal no processing needed
  return [];
}

// Market is open - pass through with timestamp
return [{
  json: {
    marketOpen: true,
    timestamp: etDate.toISOString(),
    etTime: `${hours}:${String(minutes).padStart(2, '0')}`,
    checkType: (hours === 9 && minutes === 30) ? 'first_of_day' : 'intraday'
  }
}];

// =============================================================
// WATCHLIST ALERT ENGINE
// =============================================================
// Processes batch quotes + earnings calendar.
// Compares current state against previous state (static data).
// Generates alerts for:
//   1. 50-day & 200-day SMA crosses
//   2. Intraday price move > +/-2%
//   3. Volume spike > 2x 20-day average
//   4. 52-week high/low proximity (within 1%)
//   5. Round number crosses
//   6. Earnings within 5 trading days
// Deduplicates alerts with a 2-hour cooldown.
// =============================================================

const UNIVERSE = ['AAPL','MSFT','GOOGL','AMZN','AVGO','COST','V','MA','META','NVDA','SPY'];
const COOLDOWN_MS = 2 * 60 * 60 * 1000; // 2 hours

// ---- Inputs ----
const quotes = $('FMP Batch Quote (11 Tickers)').first().json;
const earningsRaw = $('FMP Earnings Calendar (Next 7 Days)').first().json;
const triggerData = $('Market Hours Check').first().json;

// quotes from FMP come as an array
const quotesArray = Array.isArray(quotes) ? quotes : [quotes];

// Earnings calendar - filter to our universe
const earningsArray = Array.isArray(earningsRaw) ? earningsRaw : [];
const universeEarnings = earningsArray.filter(e => UNIVERSE.includes(e.symbol));

// ---- Load previous state from static data ----
const staticData = $getWorkflowStaticData('global');
const prevState = staticData.watchlistState || {};
const alertLog = staticData.alertLog || {};

// ---- Helper functions ----
function crossedAbove(prevPrice, currPrice, level) {
  if (!prevPrice || !level) return false;
  return prevPrice < level && currPrice >= level;
}

function crossedBelow(prevPrice, currPrice, level) {
  if (!prevPrice || !level) return false;
  return prevPrice > level && currPrice <= level;
}

function getRoundLevels(price) {
  const levels = [];
  let interval;
  if (price < 50) interval = 5;
  else if (price < 200) interval = 10;
  else if (price < 500) interval = 25;
  else if (price < 1000) interval = 50;
  else interval = 100;

  // Get the round levels near current price
  const base = Math.floor(price / interval) * interval;
  levels.push(base);
  levels.push(base + interval);
  if (base - interval > 0) levels.push(base - interval);
  return levels;
}

function isOnCooldown(ticker, alertType) {
  const key = `${ticker}_${alertType}`;
  const lastSent = alertLog[key];
  if (!lastSent) return false;
  return (Date.now() - lastSent) < COOLDOWN_MS;
}

function recordAlert(ticker, alertType) {
  const key = `${ticker}_${alertType}`;
  alertLog[key] = Date.now();
}

function formatNumber(num) {
  if (num >= 1e9) return (num / 1e9).toFixed(1) + 'B';
  if (num >= 1e6) return (num / 1e6).toFixed(1) + 'M';
  if (num >= 1e3) return (num / 1e3).toFixed(1) + 'K';
  return num.toString();
}

// ---- Process each ticker ----
const alerts = [];
const newState = {};

for (const q of quotesArray) {
  const ticker = q.symbol;
  if (!UNIVERSE.includes(ticker)) continue;

  const prev = prevState[ticker] || {};
  const currPrice = q.price;
  const prevPrice = prev.price;

  // Save current state
  newState[ticker] = {
    price: currPrice,
    volume: q.volume,
    priceAvg50: q.priceAvg50,
    priceAvg200: q.priceAvg200,
    yearHigh: q.yearHigh,
    yearLow: q.yearLow,
    avgVolume: q.avgVolume,
    timestamp: Date.now()
  };

  // --- 1. 50-day SMA Cross ---
  if (q.priceAvg50) {
    if (crossedAbove(prevPrice, currPrice, q.priceAvg50) && !isOnCooldown(ticker, 'MA50_CROSS_UP')) {
      alerts.push({
        ticker,
        type: 'SMA CROSS (Bullish)',
        icon: '\u2B06',
        detail: `Price $${currPrice.toFixed(2)} crossed ABOVE 50-day SMA ($${q.priceAvg50.toFixed(2)})`,
        action: 'Momentum signal ACTIVE -- eligible for CSP and long position entry',
        price: currPrice,
        level: q.priceAvg50,
        priority: 'HIGH'
      });
      recordAlert(ticker, 'MA50_CROSS_UP');
    }
    if (crossedBelow(prevPrice, currPrice, q.priceAvg50) && !isOnCooldown(ticker, 'MA50_CROSS_DOWN')) {
      alerts.push({
        ticker,
        type: 'SMA CROSS (Bearish)',
        icon: '\u2B07',
        detail: `Price $${currPrice.toFixed(2)} crossed BELOW 50-day SMA ($${q.priceAvg50.toFixed(2)})`,
        action: 'Momentum signal LOST -- reduce or avoid new long exposure',
        price: currPrice,
        level: q.priceAvg50,
        priority: 'HIGH'
      });
      recordAlert(ticker, 'MA50_CROSS_DOWN');
    }
  }

  // --- 200-day SMA Cross ---
  if (q.priceAvg200) {
    if (crossedAbove(prevPrice, currPrice, q.priceAvg200) && !isOnCooldown(ticker, 'MA200_CROSS_UP')) {
      alerts.push({
        ticker,
        type: '200-DAY SMA CROSS (Bullish)',
        icon: '\u2B06\u2B06',
        detail: `Price $${currPrice.toFixed(2)} crossed ABOVE 200-day SMA ($${q.priceAvg200.toFixed(2)})`,
        action: 'Major trend signal -- long-term bullish. Review for position building.',
        price: currPrice,
        level: q.priceAvg200,
        priority: 'HIGH'
      });
      recordAlert(ticker, 'MA200_CROSS_UP');
    }
    if (crossedBelow(prevPrice, currPrice, q.priceAvg200) && !isOnCooldown(ticker, 'MA200_CROSS_DOWN')) {
      alerts.push({
        ticker,
        type: '200-DAY SMA CROSS (Bearish)',
        icon: '\u2B07\u2B07',
        detail: `Price $${currPrice.toFixed(2)} crossed BELOW 200-day SMA ($${q.priceAvg200.toFixed(2)})`,
        action: 'Major trend break -- avoid new long exposure. Consider hedging.',
        price: currPrice,
        level: q.priceAvg200,
        priority: 'HIGH'
      });
      recordAlert(ticker, 'MA200_CROSS_DOWN');
    }
  }

  // --- 2. Intraday Move > +/-2% ---
  const intradayChangePct = q.changesPercentage;
  if (Math.abs(intradayChangePct) >= 2 && !isOnCooldown(ticker, 'BIG_MOVE')) {
    const direction = intradayChangePct > 0 ? 'UP' : 'DOWN';
    alerts.push({
      ticker,
      type: `BIG MOVE ${direction}`,
      icon: intradayChangePct > 0 ? '\u{1F7E2}' : '\u{1F534}',
      detail: `Intraday move: ${intradayChangePct > 0 ? '+' : ''}${intradayChangePct.toFixed(2)}% ($${currPrice.toFixed(2)})`,
      action: direction === 'DOWN'
        ? 'Unusual weakness -- check for news. Potential CSP entry if fundamentals intact.'
        : 'Unusual strength -- check for news. Avoid chasing; wait for pullback.',
      price: currPrice,
      changePct: intradayChangePct,
      priority: Math.abs(intradayChangePct) >= 5 ? 'HIGH' : 'MEDIUM'
    });
    recordAlert(ticker, 'BIG_MOVE');
  }

  // --- 3. Volume Spike > 2x Average ---
  if (q.volume && q.avgVolume && q.avgVolume > 0) {
    const volRatio = q.volume / q.avgVolume;
    if (volRatio >= 2 && !isOnCooldown(ticker, 'VOLUME_SPIKE')) {
      alerts.push({
        ticker,
        type: 'VOLUME SPIKE',
        icon: '\u{1F4CA}',
        detail: `Volume: ${formatNumber(q.volume)} (${volRatio.toFixed(1)}x avg ${formatNumber(q.avgVolume)})`,
        action: 'Possible institutional activity -- monitor for direction confirmation.',
        price: currPrice,
        volume: q.volume,
        avgVolume: q.avgVolume,
        volRatio: volRatio,
        priority: 'MEDIUM'
      });
      recordAlert(ticker, 'VOLUME_SPIKE');
    }
  }

  // --- 4. 52-Week High/Low Proximity ---
  if (q.yearHigh && currPrice >= q.yearHigh * 0.99 && !isOnCooldown(ticker, '52W_HIGH')) {
    alerts.push({
      ticker,
      type: '52-WEEK HIGH',
      icon: '\u{1F451}',
      detail: `Price $${currPrice.toFixed(2)} within 1% of 52-week high ($${q.yearHigh.toFixed(2)})`,
      action: 'At resistance -- watch for breakout or reversal. Tighten stops on longs.',
      price: currPrice,
      level: q.yearHigh,
      priority: 'MEDIUM'
    });
    recordAlert(ticker, '52W_HIGH');
  }

  if (q.yearLow && currPrice <= q.yearLow * 1.01 && !isOnCooldown(ticker, '52W_LOW')) {
    alerts.push({
      ticker,
      type: '52-WEEK LOW',
      icon: '\u26A0',
      detail: `Price $${currPrice.toFixed(2)} within 1% of 52-week low ($${q.yearLow.toFixed(2)})`,
      action: 'At support -- potential CSP opportunity if thesis intact. High risk zone.',
      price: currPrice,
      level: q.yearLow,
      priority: 'HIGH'
    });
    recordAlert(ticker, '52W_LOW');
  }

  // --- 5. Round Number Crosses ---
  if (prevPrice) {
    const roundLevels = getRoundLevels(currPrice);
    for (const level of roundLevels) {
      if (crossedAbove(prevPrice, currPrice, level) && !isOnCooldown(ticker, `ROUND_${level}`)) {
        alerts.push({
          ticker,
          type: 'ROUND NUMBER CROSS',
          icon: '\u{1F4B0}',
          detail: `Price crossed above $${level}`,
          action: `Psychological level $${level} -- watch for momentum continuation.`,
          price: currPrice,
          level: level,
          priority: 'LOW'
        });
        recordAlert(ticker, `ROUND_${level}`);
      }
      if (crossedBelow(prevPrice, currPrice, level) && !isOnCooldown(ticker, `ROUND_${level}`)) {
        alerts.push({
          ticker,
          type: 'ROUND NUMBER BREAK',
          icon: '\u{1F4B0}',
          detail: `Price broke below $${level}`,
          action: `Lost $${level} support -- watch for follow-through selling.`,
          price: currPrice,
          level: level,
          priority: 'LOW'
        });
        recordAlert(ticker, `ROUND_${level}`);
      }
    }
  }
}

// --- 6. Earnings Proximity (within 5 trading days) ---
const today = new Date();
for (const earning of universeEarnings) {
  const earningsDate = new Date(earning.date);
  const diffDays = Math.ceil((earningsDate - today) / (1000 * 60 * 60 * 24));
  if (diffDays > 0 && diffDays <= 7 && !isOnCooldown(earning.symbol, 'EARNINGS_PROXIMITY')) {
    alerts.push({
      ticker: earning.symbol,
      type: 'EARNINGS APPROACHING',
      icon: '\u{1F4C5}',
      detail: `Earnings on ${earning.date} (${diffDays} day${diffDays > 1 ? 's' : ''} away)`,
      action: 'Review open options positions. Close or roll CSPs expiring near earnings. Do NOT sell new options through earnings unless planned.',
      price: (newState[earning.symbol] || {}).price,
      earningsDate: earning.date,
      daysAway: diffDays,
      priority: diffDays <= 2 ? 'HIGH' : 'MEDIUM'
    });
    recordAlert(earning.symbol, 'EARNINGS_PROXIMITY');
  }
}

// --- Save state ---
staticData.watchlistState = newState;
staticData.alertLog = alertLog;

// --- Filter out LOW priority round-number alerts if there are too many ---
let finalAlerts = alerts;
if (finalAlerts.length > 10) {
  finalAlerts = finalAlerts.filter(a => a.priority !== 'LOW');
}

// --- Return alerts ---
if (finalAlerts.length === 0) {
  return [{ json: { noAlerts: true, timestamp: triggerData.etTime } }];
}

return finalAlerts.map(a => ({ json: a }));

// =============================================================
// FORMAT TELEGRAM MESSAGE
// =============================================================
// Groups alerts by ticker, formats for Telegram readability.
// Uses Telegram MarkdownV2 formatting.
// =============================================================

const items = $input.all();
const alerts = items.map(i => i.json);

// Group alerts by ticker
const grouped = {};
for (const alert of alerts) {
  if (!grouped[alert.ticker]) grouped[alert.ticker] = [];
  grouped[alert.ticker].push(alert);
}

// Build timestamp
const now = new Date();
const etString = now.toLocaleString('en-US', { timeZone: 'America/New_York' });

let message = `WATCHLIST ALERT -- ${etString}\n`;
message += `${'='.repeat(40)}\n\n`;

for (const [ticker, tickerAlerts] of Object.entries(grouped)) {
  for (const alert of tickerAlerts) {
    message += `${alert.ticker} -- ${alert.type}\n`;
    message += `${alert.detail}\n`;
    if (alert.price) {
      message += `Price: $${alert.price.toFixed(2)}`;
      if (alert.changePct) message += ` (${alert.changePct > 0 ? '+' : ''}${alert.changePct.toFixed(2)}%)`;
      message += `\n`;
    }
    message += `Action: ${alert.action}\n`;
    message += `\n`;
  }
}

message += `---\nAltamira Capital | Watchlist Monitor`;

// Ensure message is under Telegram 4096 char limit
if (message.length > 4000) {
  message = message.substring(0, 3950) + '\n\n... (truncated, too many alerts)';
}

return [{
  json: {
    message,
    alertCount: alerts.length,
    tickers: Object.keys(grouped),
    timestamp: etString
  }
}];

// =============================================================
// FORMAT GOOGLE SHEETS ROWS
// =============================================================
// Converts each alert into a row for the Watchlist Alerts sheet.
// =============================================================

const items = $('Alert Engine').all();
const alerts = items.filter(i => !i.json.noAlerts);

if (alerts.length === 0) return [];

const now = new Date();
const etString = now.toLocaleString('en-US', { timeZone: 'America/New_York' });
const dateStr = now.toISOString().split('T')[0];

return alerts.map(item => {
  const a = item.json;
  return {
    json: {
      Date: dateStr,
      Time: etString.split(', ')[1] || etString,
      Ticker: a.ticker,
      'Alert Type': a.type,
      Price: a.price ? `$${a.price.toFixed(2)}` : '',
      Level: a.level ? `$${a.level}` : '',
      Detail: a.detail,
      Action: a.action,
      Priority: a.priority
    }
  };
});
